  "schema-self-check",
  // 单用户 Worker 上有 runTask(uuid, env)：只跑指定那一条任务。
  "worker-run-task",
  // 用户级 LLM 凭据存储：PUT/GET/DELETE /llm-credentials，任务 payload 认
